import RNA, random, time, sys
target = "((..(((((........(.((..((.(.....(....).((((((((.........((......((((.....))))......))...((..((.......(..(......)..)..((..((.....((....)).((((.....(((.....(..((.(...).))..).....))).((((...(.......(..(.((...)).)..).......)...))))........)))).....((((((...)))))).))..))...........))..)).........(..((((....))((((((.....(........).....))))))..))..)...))))))))........).))..)).).....(.......).)))))..))."
stack=[]; pairs=[None]*len(target)
for i,c in enumerate(target):
    if c=='(': stack.append(i)
    elif c==')':
        j=stack.pop(); pairs[j]=i; pairs[i]=j
def dist(s):
    return RNA.bp_distance(RNA.fold_compound(s).mfe()[0], target)
seed=""
print("seed dist", dist(seed))
paired_pos=[i for i,j in enumerate(pairs) if j is not None]
def climb(start, deadline):
    random.seed()
    cur=start; cur_d=dist(cur)
    best, best_d=cur, cur_d
    while time.time()<deadline and best_d>0:
        c=list(cur)
        n=random.choice([1,1,1,2,3])
        for _ in range(n):
            if random.random()<0.7: i=random.choice(paired_pos)
            else: i=random.randrange(len(c))
            c[i]=random.choice('ACGU')
        c=''.join(c)
        d=dist(c)
        if d<cur_d or (d==cur_d and random.random()<0.45):
            cur,cur_d=c,d
            if d<best_d: best,best_d=c,d
    return best,best_d
best,bd=climb(seed, time.time()+170)
print("best",bd)
print(best)
